<script>
let page=0, age="", sex="", query="", selected=[];
const home=document.getElementById('homePage'), checker=document.getElementById('checkerPage'), content=document.getElementById('cardContent');
const symptoms=['pounding headache','dull headache','migraine headache','severe headache','headache in back of head','headache in front of head','headache behind ears','headache on temples','one sided headache','tension headache','repeated headaches','sudden severe headache','headache in the morning','headache','None of the above'];
function showChecker(){home.style.display='none';checker.style.display='block';render()}
function showHome(){home.style.display='block';checker.style.display='none'}
document.getElementById('navChecker').onclick=showChecker;
document.getElementById('homeBtn').onclick=showHome;
function tabs(){document.querySelectorAll('.tab').forEach((x,i)=>{x.classList.toggle('active',i===page)})}
function bodyFigure(){return `<div class="body-area"><div class="body"><div class="head"></div><div class="neck"></div><div class="torso"></div><div class="arm left"></div><div class="arm right"></div><div class="leg left"></div><div class="leg right"></div></div></div>`}
function render(){
 tabs();
 let html='';
 if(page===0) html=`<div class="card-body info-content"><div class="info-title"><em>WebMD</em> Symptom Checker <small style="color:#148eb9;font-size:12px">WITH BODY MAP</small></div><div class="info-sub">Identify possible conditions and treatment related to your symptoms.</div><div class="notice">This tool does not provide medical advice. <span style="color:#178aac">See additional information⌄</span></div><div class="form-row"><div class="field"><label>Age</label><input id="age" class="age" value="${age}" maxlength="3"></div><div class="field"><label>Sex</label><div class="sex"><button class="btn ${sex==='Male'?'selected':''}" data-sex="Male">Male</button><button class="btn ${sex==='Female'?'selected':''}" data-sex="Female">Female</button></div></div></div><button id="infoContinue" class="continue ${age&&sex?'':'disabled'} btn">Continue　›</button></div>`;
 if(page===1) html=`<div class="card-body symptoms-content"><div class="symptom-left"><h2>What are your symptoms?</h2><input id="symptomInput" class="symptom-input" placeholder="Type your main symptom here" value="${query}">${query?`<div class="search-results">${symptoms.filter(s=>s.toLowerCase().includes(query.toLowerCase())).map(s=>`<div class="result"><b>${s}</b><button class="add btn" data-add="${s}">ADD</button></div>`).join('')}</div>`:''}<div class="my-symptoms"><h3>${selected.length?'My Symptoms':'No symptoms added'}</h3>${selected.map(x=>`<div class="my-row">${x}</div>`).join('')}</div></div>${bodyFigure()}</div>`;
 if(page===2) html=`<div class="card-body conditions"><div class="condition-list"><h3>Conditions that match your symptoms</h3><small style="color:#168eb5">UNDERSTANDING YOUR RESULTS　●</small><div class="match"><strong>Migraine Headache (Adult)</strong><div class="bars">▰▰▰▰</div>STRONG match</div><div class="match"><strong>Tension Headache</strong><div class="bars">▰▰▰</div>Moderate match</div><div class="match"><strong>Cluster Headache</strong><div class="bars">▰▰▰</div>Moderate match</div></div><div class="summary"><p>Gender　${sex}　　　 Age　${age}</p><hr><p>My Symptoms</p><b>${selected.join(', ')}</b><hr><button class="btn" style="padding:12px 45px;background:#fff;border:1px solid #ddd">◌　Start Over</button></div></div>`;
 if(page===3) html=`<div class="card-body details"><div class="condition-list"><h3>Conditions that match your symptoms</h3><div class="match"><strong>Migraine Headache (Adult)</strong><div class="bars">▰▰▰▰</div>STRONG match</div><div class="match"><strong>Tension Headache</strong><div class="bars">▰▰▰</div>Moderate match</div><div class="match"><strong>Cluster Headache</strong><div class="bars">▰▰▰</div>Moderate match</div></div><article class="detail-main"><h1>Migraine Headache</h1><small>Migraine | Cephalgia | Vascular headache</small><hr><h2>Symptoms</h2><p>The most common symptoms of migraine include a dull or severe headache that may be worse on one side of the head, and a throbbing, pulsating, or pounding in the head. Other symptoms may include loss of appetite, nausea and vomiting, sensitivity to sound or light, chills, sweating, numbness or tingling, and increased urination.</p><h2>How Common</h2><p>About 1 in 10 people have migraine headaches.</p><h2>Overview</h2><p>Migraines are a common type of headache that can cause severe pain. They can last for a few hours or a few days and may cause throbbing, sensitivity to sound or light, nausea, or vomiting. Migraines are caused by abnormal brain activity that is triggered by certain foods, stress, or other factors.</p><a class="btn">Learn More about Migraine Symptoms &gt;</a><div class="interested"><div class="article-card"><b>Migraine Headache Made Worse By</b><p>Movement, bright lights and loud sounds, smoking, and alcohol.</p></div><div class="article-card"><b>Migraine Headache</b><p>Migraines are a common type of headache that can cause severe pain.</p></div></div><h2>Risk Factors</h2><p>Risk factors for migraine include being a woman, being under age 40, and having a family history of migraine.</p><h2>Diagnosed By</h2><p>To diagnose migraine, your doctor will take a medical history and do a physical exam.</p><button class="continue btn">Treatment Options　›</button></article></div>`;
 content.innerHTML=html;
 let bc=document.getElementById('bottomContinue'); bc.classList.toggle('disabled',page===0?(!(age&&sex)):page===1?selected.length===0:false);
 attach();
}
function attach(){
 const a=document.getElementById('age'); if(a){a.oninput=()=>{age=a.value;render()};document.querySelectorAll('[data-sex]').forEach(b=>b.onclick=()=>{sex=b.dataset.sex;render()});document.getElementById('infoContinue').onclick=()=>{if(age&&sex){page=1;render()}}}
 const inp=document.getElementById('symptomInput');if(inp){inp.oninput=()=>{query=inp.value;render()};document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>openModal())}
 document.getElementById('bottomContinue').onclick=()=>{if(page===1&&selected.length){page=2;render()}else if(page===2){page=3;render()}};
 document.querySelector('.prev').onclick=()=>{if(page>0){page--;render()}}
}
function openModal(){document.getElementById('modalBg').style.display='block';document.getElementById('checkList').innerHTML=symptoms.map(s=>`<label class="check-item"><input type="checkbox" value="${s}" ${selected.includes(s)?'checked':''}>${s}</label>`).join('');document.querySelectorAll('#checkList input').forEach(x=>x.onchange=()=>document.getElementById('doneBtn').classList.toggle('enabled',[...document.querySelectorAll('#checkList input:checked')].length>0))}
document.getElementById('doneBtn').onclick=()=>{selected=[...document.querySelectorAll('#checkList input:checked')].map(x=>x.value).filter(x=>x!=='None of the above');document.getElementById('modalBg').style.display='none';query='';render()};
document.getElementById('skipBtn').onclick=()=>{document.getElementById('modalBg').style.display='none'};
</script>
